requireAjaxRole(['SUPER_ADMIN']);verifyAjaxCsrf();
$id=(int)($_POST['id']??0);$action=strtoupper(trim((string)($_POST['action']??'')));$comment=trim((string)($_POST['comment']??''));if(!$id||!in_array($action,['APPROVE_LOCAL','INTEGRATE_NATIONAL','REFUSE'],true))jsonResponse(false,'Action invalide.',[],422);
try{
$pdo->beginTransaction();$s=$pdo->prepare("SELECT f.*,eas.source_template_id FROM facultes f JOIN etablissement_academic_settings eas ON eas.etablissement_id=f.etablissement_id WHERE f.id=? AND f.ajoute_localement=1 LIMIT 1 FOR UPDATE");$s->execute([$id]);$f=$s->fetch(PDO::FETCH_ASSOC);if(!$f)throw new RuntimeException('Ajout local introuvable.');$uid=(int)($_SESSION['user_id']??0)?:null;
if($action==='APPROVE_LOCAL'){$pdo->prepare("UPDATE facultes SET validation_statut='VALIDE_LOCAL',actif=1,reviewed_by_user_id=?,reviewed_at=NOW(),review_comment=? WHERE id=?")->execute([$uid,$comment?:null,$id]);$message='Unité validée pour cet établissement uniquement.';}
